urlset:
{%- set posts_section = get_section(path="posts/_index.md") -%}
{%- for sitemap_entry in entries -%}
    {%- set_global is_draft_post = false -%}
    {%- for page in posts_section.pages -%}
        {%- if page.draft and sitemap_entry.permalink == page.permalink -%}
            {%- set_global is_draft_post = true -%}
        {%- endif -%}
    {%- endfor -%}
    {%- if not is_draft_post -%}

        {{ sitemap_entry.permalink | escape_xml | safe }}
        {%- if sitemap_entry.updated -%}
        {{ sitemap_entry.updated }}
        {%- endif -%}

    {%- endif -%}
{%- endfor -%}
